/**
 * types.d.ts
 *
 * Shared TypeScript type definitions for the ImageGeneraterAPI server.
 * These types are consumed via JSDoc @typedef imports in plain JS files —
 * no TypeScript compilation is required.
 *
 * Usage in a JS file:
 *   @typedef {import('./types').Tag} Tag
 */

// ─── Enums / Union Types ──────────────────────────────────────────────────────

/** The four supported tag categories. */
export type TagType = "character" | "prop" | "outfit" | "location";

/** The five asset groups stored on each tag record. */
export type AssetGroup = "face" | "body" | "prop" | "outfit" | "location";

/** Allowed horizontal screen-placement values for characters. */
export type PositionHorizontal =
    | "far_left"
    | "left"
    | "center_left"
    | "center"
    | "center_right"
    | "right"
    | "far_right"
    | null;

/** Allowed vertical screen-placement values for characters. */
export type PositionVertical =
    | "top"
    | "upper_middle"
    | "middle"
    | "lower_middle"
    | "bottom"
    | null;

/** Allowed depth-placement values for characters. */
export type PositionDepth = "foreground" | "midground" | "background" | null;

/** Allowed spatial-relation values between characters. */
export type Relation =
    | "left_of"
    | "right_of"
    | "in_front_of"
    | "behind"
    | "next_to"
    | "between"
    | "overlapping"
    | "facing"
    | null;

/** Allowed character facing / orientation values. */
export type FacingValue =
    | "camera"
    | "left"
    | "right"
    | "away"
    | "toward_subject"
    | "downward"
    | "upward"
    | "three_quarter_left"
    | "three_quarter_right"
    | null;

/** Allowed character stance values. */
export type StanceValue =
    | "standing"
    | "sitting"
    | "kneeling"
    | "crouching"
    | "lying"
    | "leaning"
    | "walking"
    | "running"
    | "dancing"
    | null;

/** Allowed support-surface values for characters. */
export type SupportValue =
    | "floor"
    | "bed"
    | "chair"
    | "couch"
    | "wall"
    | "table"
    | "car"
    | "ground"
    | "stairs"
    | null;

// ─── Asset / Tag Records ─────────────────────────────────────────────────────

/**
 * A single uploaded image asset stored on a tag.
 * After a WaveSpeed upload the `url` field is always present.
 * During in-memory collage processing a `buffer` may also be attached,
 * but it is never persisted to disk.
 */
export interface TagAsset {
    /** WaveSpeed CDN URL for the uploaded asset. */
    url: string;
    filename?: string;
    mimeType?: string;
    /** Set to "collage" when this asset was generated by merging multiple sources. */
    source?: string;
    /** True when this asset replaced multiple source images via collapsing. */
    collapsed?: boolean;
}

/** All image asset groups stored on a tag record. */
export interface TagAssets {
    face: TagAsset[];
    body: TagAsset[];
    prop: TagAsset[];
    outfit: TagAsset[];
    location: TagAsset[];
}

/**
 * Lock descriptions that constrain how a tag is rendered.
 * Characters can have all three fields; other tag types only use basicDescription.
 */
export interface TagLock {
    /** General appearance / object description used for all tag types. */
    basicDescription?: string;
    /** Facial appearance description. Characters only. */
    appearanceDescription?: string;
    /** Body shape / build description. Characters only. */
    bodyDescription?: string;
}

/** A complete tag record as stored in tags.json. */
export interface Tag {
    key: string;
    type: TagType;
    assets: TagAssets;
    lock: TagLock;
    meta: Record<string, unknown>;
}

// ─── Database Shapes ─────────────────────────────────────────────────────────

/** Raw shape of tags.json on disk. */
export interface TagDb {
    tags: Record<string, Tag>;
}

/** A single saved generation result in the gallery. */
export interface GalleryEntry {
    id: string;
    imageUrl: string;
    userPrompt: string;
    compiledPrompt: string | null;
    compiledImages: string[];
    referenceImageUrls: string[];
    size: string;
    cost: string | null;
    timestamp: string;
}

/** Raw shape of gallery.json on disk. */
export interface GalleryDb {
    entries: GalleryEntry[];
}

// ─── WaveSpeed API ────────────────────────────────────────────────────────────

/** Return value from a successful WaveSpeed binary upload. */
export interface WaveSpeedUploadResult {
    /** Publicly accessible download URL for the uploaded file. */
    url: string;
    filename: string;
    /** File size in bytes. */
    size: number;
    /** Raw response body from the WaveSpeed API. */
    raw: unknown;
}

/** Parameters for a Seedream image generation / edit call. */
export interface SeedreamEditOptions {
    /** WaveSpeed URLs of reference images. Empty array triggers a text-only generation. */
    images: string[];
    prompt: string;
    size?: string;
    enableSyncMode?: boolean;
    enableBase64Output?: boolean;
}

/** Parameters for a text-only Any LLM call. */
export interface AnyLLMOptions {
    prompt: string;
    systemPrompt?: string;
    model?: string;
    temperature?: number;
    maxTokens?: number;
    reasoning?: boolean;
    priority?: string;
    enableSyncMode?: boolean;
}

/** Parameters for a vision-capable Any LLM call. Extends AnyLLMOptions with image URLs. */
export interface AnyLLMVisionOptions extends AnyLLMOptions {
    /** Publicly accessible image URLs to pass to the vision model. */
    images?: string[];
}

// ─── Image Processing ─────────────────────────────────────────────────────────

/** Parsed result of a base64 image string. */
export interface ParsedImage {
    mimeType: string;
    /** File extension without the leading dot (e.g. "jpg", "png"). */
    ext: string;
    buffer: Buffer;
}

/** Normalized object ready to be passed to uploadBufferToWaveSpeed. */
export interface UploadObject {
    buffer: Buffer;
    mimeType: string;
    ext: string;
}

/** Options for createImageGridFromBuffers. */
export interface CollageOptions {
    /** Size in pixels for each grid cell. Defaults to 1024. */
    cellSize?: number;
    /** CSS hex color for the background canvas. Defaults to "#111111". */
    background?: string;
}

// ─── Prompt Compiler ─────────────────────────────────────────────────────────

/** Structured screen-position for a character in the plan. */
export interface CharacterPosition {
    horizontal: PositionHorizontal;
    vertical: PositionVertical;
    depth: PositionDepth;
}

/** Describes a character's position relative to another character. */
export interface RelativePosition {
    relation: string;
    /** Primary target tag key for single-target relations. */
    targetTag: string | null;
    /** All target tag keys, used for multi-target relations like "between". */
    targetTags: string[];
}

/** A single character entry within a normalized parsed plan. */
export interface PlanCharacter {
    tag: string;
    /** Human-readable label extracted from the prompt (e.g. "the woman on the left"). */
    label: string;
    position: CharacterPosition;
    relativePosition: RelativePosition | null;
    facing: FacingValue;
    stance: StanceValue;
    support: SupportValue;
    poseDescription: string;
    wardrobeDescription: string;
    /** Whether to apply the face/appearance reference images for this character. */
    useAppearance: boolean;
    /** Whether to apply the body-shape reference image for this character. */
    useBodyShape: boolean;
}

/** A single prop entry within a normalized parsed plan. */
export interface PlanProp {
    tag: string;
    /** Prose description of where / how the prop appears in the scene. */
    placement: string;
    /** Whether to include the tag's basicDescription lock text. */
    useBasicLock: boolean;
}

/** A single outfit entry within a normalized parsed plan. */
export interface PlanOutfit {
    tag: string;
    placement: string;
    useBasicLock: boolean;
}

/** A single location entry within a normalized parsed plan. */
export interface PlanLocation {
    tag: string;
    useBasicLock: boolean;
}

/** The normalized output produced by the planning LLM and validated by normalizeParsedPlan. */
export interface ParsedPlan {
    sceneDescription: string;
    characters: PlanCharacter[];
    props: PlanProp[];
    outfits: PlanOutfit[];
    locations: PlanLocation[];
    extraDirectives: string[];
}

/** Lightweight tag summary sent to the planning LLM (no asset URLs). */
export interface TagSummary {
    key: string;
    type: TagType;
    assetCounts: Record<AssetGroup, number>;
    lock: {
        basicDescription: string;
        appearanceDescription: string;
        bodyDescription: string;
    };
}

/** LLM call tuning parameters shared across compiler functions. */
export interface LLMOptions {
    model?: string;
    temperature?: number;
    maxTokens?: number;
    reasoning?: boolean;
    priority?: string;
    enableSyncMode?: boolean;
}

/** Options for enrichTagLocksWithVision. Extends LLMOptions with vision-specific flags. */
export interface VisionEnrichOptions extends LLMOptions {
    /** Set to true to actually run vision enrichment; false (default) is a no-op. */
    enable?: boolean;
    /** Set to true to overwrite existing lock descriptions even if already populated. */
    force?: boolean;
}

/** Full result returned by compilePrompt and buildRawPromptFromPlan. */
export interface BuildRawPromptResult {
    rawPrompt: string;
    /** Ordered array of WaveSpeed image URLs fed to the Seedream model. */
    images: string[];
    /** Image-reference directive lines injected into the prompt. */
    directives: string[];
    /** Scene prose lines that open the prompt. */
    sceneLines: string[];
}

/** Full result returned by compilePrompt. */
export interface CompileResult extends BuildRawPromptResult {
    parsedPlan: ParsedPlan;
    /** Tag records keyed by tag key, after collapsing and vision enrichment. */
    tagMap: Record<string, Tag>;
}
